{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C54"],
      "claim": "Procainamide, a para-amino benzamide with a diethylaminoethyl side chain, has about 75% oral systemic bioavailability in patients; the query shares the benzamide core and a basic aminoethyl-type side chain, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "N-acetylprocainamide, a close benzamide analogue with a para-acetamido group and diethylaminoethyl side chain, has absolute oral bioavailability of 87.2% in humans by stable-isotope IV/oral comparison, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Sematilide, a para-methanesulfonamido benzamide with a basic aminoethyl side chain, has absolute oral bioavailability of about 46% from plasma in humans; although lower than procainamide/NAPA, it remains well above the 20% threshold and supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Molsidomine, which contains a morpholine ring like the query, has absolute oral bioavailability of 44 ± 15% in humans, supporting F ≥ 20% for the morpholine-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Haloperidol, a 4-chlorophenyl drug with a basic amine, has oral bioavailability of 60–70% in humans; despite lower structural similarity, it supports the expectation that the 4-chlorophenyl and basic amine query is not inherently low-bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Loperamide has very low absolute oral bioavailability (0.3%) in humans, attributed to P-gp efflux and first-pass metabolism; however, the query is much smaller, less lipophilic, and lacks the P-gp-prone features, so this contradictory evidence has limited transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small 4-chlorobenzamide with a morpholinoethyl side chain. The closest experimental analogues—procainamide, N-acetylprocainamide, and sematilide—are para-substituted benzamides with basic aminoethyl side chains and show human oral bioavailability values of roughly 46–92%, all above the 20% threshold. Haloperidol and molsidomine also support F ≥ 20%. The only strong low-F analogue, loperamide, is structurally dissimilar and its low bioavailability is driven by P-gp efflux and high lipophilicity not expected for the query. Therefore, the prediction is high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself in the supplied evidence set.",
    "First-pass metabolism and transporter efflux for the query are not directly measured; extrapolation from benzamide analogues assumes similar metabolic stability.",
    "Human data for the closest analogues come from different drug classes and dosing conditions; no fasted-state-specific query data are available."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C54"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "procainamide-like benzamides"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C46"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "N-acetylprocainamide/acecainide"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C37"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "sematilide benzamides"
    },
    {
      "applicability": "low",
      "card_ids": ["C10"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "loperamide"
    }
  ],
  "revision_action": "initial"
}

